270:                     values.put(key, List.of(Map.of("domain", recordMap.get(key))));
271:                     break;
272:                 case "workspace_id", "avatar_url":
273:                     values.put(key, recordMap.get(key));
274:                     break;
275:                 case "user_id", "stage", "owner":
276:                     if (recordType.equals(DEALS) && key.equals("owner")) {
277:                         values.put(key, List.of(Map.of("referenced_actor_id", recordMap.get(key),
278:                             "referenced_actor_type", "workspace-member")));
279:                     } else {
280:                         values.put(key, recordMap.get(key));
281:                     }
282:                     break;
283:                 case "name", "description", "instagram", "facebook", "linkedin", "job_title":
284:                     if (recordType.equals(DEALS) || recordType.equals(WORKSPACES)) {
285:                         values.put(key, recordMap.get(key));
286:                     } else {
287:                         values.put(key, List.of(Map.of("value", recordMap.get(key))));
288:                     }
289:                     break;
290:                 case "foundation_date":
291:                     LocalDate foundationDate = LocalDate.parse(recordMap.get(key)
292:                         .toString());
293:                     values.put(key, List.of(Map.of("value", foundationDate.toString())));
294:                     break;
295:                 case "email_address":
296:                     if (recordType.equals(USERS)) {
297:                         values.put("primary_email_address", recordMap.get(key));
298:                     } else {
299:                         values.put("email_addresses", List.of(recordMap.get(key)));
300:                     }
301:                     break;
302: 
303:                 case "estimated_arr_usd", "employee_range":
304:                     values.put(key, List.of(Map.of("option", recordMap.get(key))));
305:                     break;
306:                 case "categories":
307:                     if (recordMap.get(key) instanceof List<?> categoriesList)
308:                         values.put(key, categoriesList.stream()
309:                             .map(category -> Map.of("option", category))
310:                             .toList());
311:                     break;
312: 
313:                 case "associated_deals":
314:                     if (recordMap.get(key) instanceof List<?> dealsList)
315:                         values.put(key, dealsList.stream()
316:                             .map(deal -> Map.of("target_object", DEALS, "target_record_id", deal))
317:                             .toList());
318:                     break;
