257:     public static Map<String, Object> getRecordValues(Map<String, Object> recordMap, String recordType) {
258:         HashMap<String, Object> values = new HashMap<>();
259: 
260:         for (Entry<String, Object> property : recordMap.entrySet()) {
261:             String key = property.getKey();
262: 
263:             if (recordMap.get(key) == null)
264:                 break;
265:             switch (key) {
266:                 case "value":
267:                     values.put(key, List.of(Map.of("currency_value", recordMap.get(key))));
268:                     break;
269:                 case "domains":
270:                     values.put(key, List.of(Map.of("domain", recordMap.get(key))));
271:                     break;
272:                 case "workspace_id", "avatar_url":
273:                     values.put(key, recordMap.get(key));
274:                     break;
275:                 case "user_id", "stage", "owner":
276:                     if (recordType.equals(DEALS) && key.equals("owner")) {
277:                         values.put(key, List.of(Map.of("referenced_actor_id", recordMap.get(key),
278:                             "referenced_actor_type", "workspace-member")));
279:                     } else {
280:                         values.put(key, recordMap.get(key));
281:                     }
282:                     break;
283:                 case "name", "description", "instagram", "facebook", "linkedin", "job_title":
284:                     if (recordType.equals(DEALS) || recordType.equals(WORKSPACES)) {
285:                         values.put(key, recordMap.get(key));
286:                     } else {
287:                         values.put(key, List.of(Map.of("value", recordMap.get(key))));
288:                     }
289:                     break;
290:                 case "foundation_date":
291:                     LocalDate foundationDate = LocalDate.parse(recordMap.get(key)
292:                         .toString());
293:                     values.put(key, List.of(Map.of("value", foundationDate.toString())));
294:                     break;
295:                 case "email_address":
296:                     if (recordType.equals(USERS)) {
297:                         values.put("primary_email_address", recordMap.get(key));
298:                     } else {
299:                         values.put("email_addresses", List.of(recordMap.get(key)));
300:                     }
301:                     break;
302: 
303:                 case "estimated_arr_usd", "employee_range":
304:                     values.put(key, List.of(Map.of("option", recordMap.get(key))));
305:                     break;
306:                 case "categories":
307:                     if (recordMap.get(key) instanceof List<?> categoriesList)
308:                         values.put(key, categoriesList.stream()
309:                             .map(category -> Map.of("option", category))
310:                             .toList());
311:                     break;
312: 
313:                 case "associated_deals":
314:                     if (recordMap.get(key) instanceof List<?> dealsList)
315:                         values.put(key, dealsList.stream()
316:                             .map(deal -> Map.of("target_object", DEALS, "target_record_id", deal))
317:                             .toList());
318:                     break;
319:                 case "associated_users", "users":
320:                     if (recordMap.get(key) instanceof List<?> usersList)
321:                         values.put(key, usersList.stream()
322:                             .map(user -> Map.of("target_object", USERS, "target_record_id", user))
323:                             .toList());
324:                     break;
325:                 case "workspace", "associated_workspaces":
326:                     if (recordMap.get(key) instanceof List<?> workspacesList)
327:                         values.put(key, workspacesList.stream()
328:                             .map(workspace -> Map.of("target_object", WORKSPACES, "target_record_id", workspace))
329:                             .toList());
330:                     break;
331:                 case "associated_people":
332:                     if (recordMap.get(key) instanceof List<?> peopleList)
333:                         values.put("associated_people", peopleList.stream()
334:                             .map(person -> Map.of("target_object", PEOPLE, "target_record_id", person))
335:                             .toList());
336:                     break;
337:                 case "person":
338:                     values.put(key, Map.of("target_object", PEOPLE, "target_record_id", recordMap.get(key)));
339:                     break;
340:                 case "company", "associated_company":
341:                     if (recordType.equals(WORKSPACES)) {
342:                         values.put("company", Map.of("target_object", COMPANIES,
343:                             "target_record_id", recordMap.get("company")));
344:                     } else {
345:                         values.put(key, List.of(Map.of("target_object", COMPANIES,
346:                             "target_record_id", recordMap.get(key))));
347:                     }
348:                     break;
349:                 default:
350:                     break;
351:             }
352:         }
353: 
354:         if (recordType.equals(PEOPLE)) {
355:             addNameToValues(recordMap, values);
356:         }
357: 
358:         return values;
359:     }
