133:     public Map<String, Object> evaluate(Map<String, ?> map, Map<String, ?> context) {
134:         return evaluateInternal(map, context);
135:     }
136: 
137:     private StandardEvaluationContext createEvaluationContext(Map<String, ?> context, boolean formulaExpression) {
138:         StandardEvaluationContext evaluationContext = new StandardEvaluationContext(context);
139: 
140:         evaluationContext.addPropertyAccessor(new MapPropertyAccessor());
141: 
142:         if (formulaExpression) {
143:             evaluationContext.addMethodResolver(methodResolver());
144:         }
145: 
146:         return evaluationContext;
147:     }
