172:     @Nullable
173:     private Object evaluate(Object value, Map<String, ?> context) {
174:         if (value instanceof String string) {
175:             Expression expression;
176:             boolean formulaExpression = false;
177: 
178:             string = string.trim();
179: 
180:             if (string.equals(FORMULA_PREFIX)) {
181:                 return string;
182:             }
183: 
184:             if (string.startsWith(FORMULA_PREFIX)) {
185:                 formulaExpression = true;
186: 
187:                 try {
188:                     string = string.replaceAll("\\$\\{([^}]*)}", "$1");
189: 
190:                     if (!validateFormulaExpression(string)) {
191:                         throw new UnsupportedOperationException("Invalid formula expression: " + string);
192:                     }
193: 
194:                     expression = expressionParser.parseExpression(string.substring(1));
195:                 } catch (ParseException e) {
196:                     throw new IllegalArgumentException("Invalid formula expression: " + string, e);
197:                 }
198:             } else {
199:                 if (!validateTextExpression(string)) {
200:                     throw new IllegalArgumentException("Invalid expression: " + string);
201:                 }
202: 
203:                 expression = expressionParser.parseExpression(
204:                     string, new TemplateParserContext(ACCESSOR_PREFIX, ACCESSOR_SUFFIX));
205:             }
206: 
207:             if (expression instanceof CompositeStringExpression) { // attempt partial evaluation
208:                 return evaluate((CompositeStringExpression) expression, context);
209:             } else if (expression instanceof LiteralExpression) {
210:                 return expression.getValue();
211:             } else {
212:                 try {
213:                     return expression.getValue(createEvaluationContext(context, formulaExpression));
214:                 } catch (SpelEvaluationException e) {
215:                     if (logger.isTraceEnabled()) {
216:                         logger.trace(e.getMessage());
217:                     }
218: 
219:                     return value;
220:                 }
221:             }
222:         } else if (value instanceof List<?> list) {
223:             List<Object> evaluatedlist = new ArrayList<>();
224: 
225:             for (Object item : list) {
226:                 evaluatedlist.add(evaluate(item, context));
227:             }
228: 
229:             return evaluatedlist;
230:         } else if (value instanceof Map<?, ?> map) {
231:             return evaluateInternal(map, context);
232:         }
233: 
234:         return value;
235:     }
