237:     private Map<String, Object> evaluateInternal(Map<?, ?> map, Map<String, ?> context) {
238:         Map<String, Object> newMap = new LinkedHashMap<>();
239: 
240:         for (Entry<?, ?> entry : map.entrySet()) {
241:             newMap.put((String) entry.getKey(), evaluate(entry.getValue(), context));
242:         }
243: 
244:         return newMap;
245:     }
246: 
247:     private MethodResolver methodResolver() {
248:         return (ctx, target, name, args) -> {
249:             MethodExecutor executor = methodExecutorMap.get(name);
250: 
251:             if (executor == null) {
252:                 throw new UnsupportedOperationException("Method invocation is not allowed: " + name);
253:             }
254: 
255:             return executor;
256:         };
257:     }
258: 
259:     private static boolean validateTextExpression(String expression) {
260:         Matcher accessorMatcher = ACCESSOR_EXPRESSION_PATTERN.matcher(expression);
261: 
262:         while (accessorMatcher.find()) {
263:             String accessorContent = accessorMatcher.group(1);
264: 
265:             Matcher validAccessorMatcher = VALID_ACCESSOR_PATTERN.matcher(accessorContent);
266: 
267:             if (!validAccessorMatcher.matches()) {
268:                 return false;
269:             }
270:         }
271: 
272:         return true;
273:     }
274: 
275:     private static boolean validateFormulaExpression(String expression) {
276:         Matcher formulaMatcher = FORMULA_EXPRESSION_PATTERN.matcher(expression);
277: 
278:         return formulaMatcher.matches();
279:     }
