345:                     checkDisplayConditionsAndParameters(
346:                         parameterPath, workflowNodeName, workflow, operationType, parameterMap,
347:                         (Map<String, Object>) inputMap, displayConditionMap, dynamicPropertyTypesMap, arrayProperty,
348:                         removeParameters);
349: 
350:                     checkDisplayConditionsAndParameters(
351:                         parameterPath, workflowNodeName, workflow, operationType, parameterMap,
