450:     private static void removeParameter(String parameterName, List<Integer> indexes, Map<?, ?> parameterMap) {
451:         for (Map.Entry<?, ?> entry : parameterMap.entrySet()) {
452:             String key = (String) entry.getKey();
453: 
454:             if (key.equals(parameterName)) {
455:                 parameterMap.remove(key);
456: 
457:                 return;
458:             }
459: 
460:             if (parameterMap.get(key) instanceof List<?> subList && indexes != null && !indexes.isEmpty()) {
461:                 int index = indexes.getFirst();
462: 
463:                 if (subList.size() <= index) {
464:                     continue;
465:                 }
466: 
467:                 if (subList.get(index) instanceof Map<?, ?> subParameterMap) {
468:                     indexes.removeFirst();
469: 
470:                     removeParameter(parameterName, indexes, subParameterMap);
471:                 } else if (subList.get(index) instanceof List<?> subList2) {
472:                     if (indexes.getFirst() < subList2.size() &&
473:                         subList2.get(indexes.getFirst()) instanceof Map<?, ?> subParameterMap) {
474: 
475:                         indexes.removeFirst();
476: 
477:                         removeParameter(parameterName, indexes, subParameterMap);
478:                     } else {
479:                         indexes.removeFirst();
480:                     }
481:                 }
482:             } else if (parameterMap.get(key) instanceof Map<?, ?> subParameterMap) {
483:                 removeParameter(parameterName, indexes, subParameterMap);
484:             }
485:         }
486:     }
