488:     private static void checkDynamicPropertyType(String propertyName, Map<String, ?> dynamicPropertyTypesMap) {
489:         for (String key : new HashSet<>(dynamicPropertyTypesMap.keySet())) {
490:             if (key.equals(propertyName) || key.contains("." + propertyName) || key.startsWith(propertyName + ".") ||
491:                 key.startsWith(propertyName + "[")) {
492: 
493:                 dynamicPropertyTypesMap.remove(key);
494:             }
495:         }
496:     }
