519:     private static List<List<Integer>> findIndexes(String displayCondition, Map<String, ?> parameterMap) {
520:         List<List<Integer>> allIndexes = new ArrayList<>();
521: 
522:         if (displayCondition == null || displayCondition.isEmpty()) {
523:             return List.of();
524:         }
525: 
526:         findIndexes(displayCondition, parameterMap, new ArrayList<>(), allIndexes);
527: 
528:         return allIndexes;
529:     }
