720:             if (taskMap == null) {
721:                 throw new ConfigurationException(
722:                     "Workflow node with name: %s does not exist".formatted(workflowNodeName),
723:                     WorkflowErrorType.WORKFLOW_NODE_NOT_FOUND);
724:             }
725: 
726:             parameterMap = (Map<String, ?>) taskMap.get(WorkflowConstants.PARAMETERS);
727:             WorkflowNodeType workflowNodeType = WorkflowNodeType.ofType(
728:                 (String) taskMap.get(WorkflowConstants.TYPE));
729: 
730:             if (workflowNodeType.operation() == null) {
731:                 operationType = WorkflowNodeStructure.OperationType.TASK_DISPATCHER;
732: 
733:                 TaskDispatcherDefinition taskDispatcherDefinition =
734:                     taskDispatcherDefinitionService.getTaskDispatcherDefinition(
735:                         workflowNodeType.name(), workflowNodeType.version());
736: 
737:                 properties = taskDispatcherDefinition.getProperties();
738:             } else {
739:                 operationType = WorkflowNodeStructure.OperationType.TASK;
740: 
741:                 ActionDefinition actionDefinition = actionDefinitionService.getActionDefinition(
742:                     workflowNodeType.name(), workflowNodeType.version(),
743:                     workflowNodeType.operation());
744: 
745:                 properties = actionDefinition.getProperties();
746:             }
747:         } else {
748:             operationType = WorkflowNodeStructure.OperationType.TRIGGER;
749:             parameterMap = (Map<String, ?>) triggerMap.get(WorkflowConstants.PARAMETERS);
750:             WorkflowNodeType workflowNodeType = WorkflowNodeType.ofType(
751:                 (String) triggerMap.get(WorkflowConstants.TYPE));
752: 
753:             TriggerDefinition triggerDefinition = triggerDefinitionService.getTriggerDefinition(
754:                 workflowNodeType.name(), workflowNodeType.version(),
755:                 workflowNodeType.operation());
756: 
757:             properties = triggerDefinition.getProperties();
758:         }
759: 
760:         List<String> missingRequiredProperties = new ArrayList<>();
761: 
762:         if (parameterMap != null && properties != null) {
763:             checkRequiredProperties(properties, parameterMap, "", missingRequiredProperties);
764:         }
765: 
766:         return new WorkflowNodeStructure(operationType, parameterMap, properties, missingRequiredProperties);
767:     }
