873:     @SuppressWarnings("unchecked")
874:     private void setParameter(
875:         String[] parameterPathParts, Object value, boolean removeValue, Map<String, ?> parameterMap) {
876: 
877:         Map<String, Object> map = (Map<String, Object>) parameterMap;
878: 
879:         for (int i = 0; i < parameterPathParts.length; i++) {
880:             String pathItem = parameterPathParts[i];
881: 
882:             if (pathItem.endsWith("]")) {
883:                 String name = pathItem.substring(0, pathItem.indexOf("["));
884:                 String arrays = pathItem.substring(pathItem.indexOf("["));
885: 
886:                 List<Object> list;
887: 
888:                 if (Objects.nonNull(map.get(name))) {
889:                     list = (List<Object>) map.get(name);
890:                 } else {
891:                     list = new ArrayList<>();
892: 
893:                     map.put(name, list);
894:                 }
895: 
896:                 Matcher matcher = ARRAY_INDEX_VALUE_PATTERN.matcher(arrays);
897: 
898:                 List<Integer> arrayIndexes = new ArrayList<>();
899: 
900:                 while (matcher.find()) {
901:                     arrayIndexes.add(Integer.parseInt(matcher.group(1)));
902:                 }
903: 
904:                 for (int j = 0; j < arrayIndexes.size(); j++) {
905:                     int arrayIndex = arrayIndexes.get(j);
906: 
907:                     if (list.size() < (arrayIndex + 1)) {
908:                         for (int k = list.size(); k < (arrayIndex + 1); k++) {
909:                             list.add(null);
910:                         }
911:                     }
912: 
913:                     if (j == arrayIndexes.size() - 1) {
914:                         if (i == parameterPathParts.length - 1) {
915:                             if (removeValue) {
916:                                 list.remove(arrayIndex);
917:                             } else {
918:                                 list.set(arrayIndex, value);
919:                             }
920:                         } else {
921:                             if (list.get(arrayIndex) == null) {
922:                                 map = new HashMap<>();
923: 
924:                                 list.set(arrayIndex, map);
925:                             } else {
926:                                 map = (Map<String, Object>) list.get(arrayIndex);
927:                             }
928:                         }
929:                     } else {
930:                         if (list.get(arrayIndex) == null) {
931:                             list.set(arrayIndex, new ArrayList<>());
932:                         }
933: 
934:                         list = (List<Object>) list.get(arrayIndex);
935:                     }
936:                 }
937:             } else {
938:                 if (i < parameterPathParts.length - 1) {
939:                     if (map.containsKey(pathItem)) {
940:                         map = (Map<String, Object>) map.get(pathItem);
941:                     } else {
942:                         Map<String, Object> subParameterMap = new HashMap<>();
943: 
944:                         map.put(pathItem, subParameterMap);
