189:     protected static boolean hasExpressionVariable(String displayCondition, String parameterPath) {
190:         if ((displayCondition == null) || displayCondition.isEmpty()) {
191:             return false;
192:         }
193: 
194:         String regex = "(^|.*\\W)" + parameterPath + "(\\W.*|$)";
195: 
196:         Pattern pattern = Pattern.compile(regex);
197:         Matcher matcher = pattern.matcher(displayCondition);
198: 
199:         return matcher.find();
200:     }
201: 
202:     protected static boolean hasExpressionVariable(
203:         String displayCondition, String parameterPath, List<Integer> parameterPathIndexes) {
204: 
205:         if ((displayCondition == null) || displayCondition.isEmpty()) {
206:             return false;
207:         }
208: 
209:         if (!displayCondition.contains("[index]")) {
210:             return false;
211:         }
212: 
213:         displayCondition = replaceIndexes(displayCondition, parameterPathIndexes);
214: 
215:         return displayCondition.contains(parameterPath);
216:     }
