242:     protected void evaluateArray(
243:         String propertyName, String displayCondition, Map<String, String> displayConditionMap,
244:         Map<String, Object> inputMap, Map<String, Object> outputs, Map<String, ?> parameterMap) {
245: 
246:         List<List<Integer>> indexesList = collectAllIndexCombinations(displayCondition, parameterMap);
247: 
248:         if (indexesList.isEmpty()) {
249:             boolean result = evaluateWithOutputs(displayCondition, inputMap, outputs, parameterMap);
250: 
251:             if (result) {
252:                 displayConditionMap.put(displayCondition, propertyName);
253:             }
254:         } else {
255:             for (List<Integer> indexes : indexesList) {
256:                 String updatedDisplayCondition = displayCondition.contains("[index]")
257:                     ? replaceIndexes(displayCondition, indexes) : displayCondition;
258: 
259:                 if (displayConditionMap.containsKey(updatedDisplayCondition)) {
260:                     continue;
261:                 }
262: 
263:                 boolean result = evaluateWithOutputs(updatedDisplayCondition, inputMap, outputs, parameterMap);
264: 
265:                 if (result) {
266:                     String indexesString = indexes.stream()
267:                         .map(String::valueOf)
268:                         .collect(Collectors.joining("_"));
269: 
270:                     displayConditionMap.put(updatedDisplayCondition, String.join("_", indexesString, propertyName));
271:                 }
272:             }
273:         }
274:     }
