276:     private void checkDependOn(
277:         String name, List<? extends BaseProperty> properties, Map<String, ?> parameterMap,
278:         Map<String, ?> dynamicPropertyTypesMap) {
279: 
280:         for (BaseProperty property : properties) {
281:             List<String> dependOnPropertyNames = List.of();
282: 
283:             if (property instanceof OptionsDataSourceAware optionsDataSourceAware) {
284:                 OptionsDataSource optionsDataSource = optionsDataSourceAware.getOptionsDataSource();
285: 
286:                 if (optionsDataSource == null) {
287:                     continue;
288:                 }
289: 
290:                 dependOnPropertyNames = optionsDataSource.getOptionsLookupDependsOn();
291:             } else if (property instanceof DynamicPropertiesProperty dynamicPropertiesProperty) {
292:                 PropertiesDataSource propertiesDataSource = dynamicPropertiesProperty.getPropertiesDataSource();
293: 
294:                 if (propertiesDataSource == null) {
295:                     continue;
296:                 }
297: 
298:                 dependOnPropertyNames = propertiesDataSource.getPropertiesLookupDependsOn();
299:             }
300: 
301:             if (dependOnPropertyNames.contains(name)) {
302:                 parameterMap.remove(property.getName());
303: 
304:                 checkDynamicPropertyType(property.getName(), dynamicPropertyTypesMap);
305:             }
306:         }
307:     }
