385:     @SuppressWarnings("unchecked")
386:     private void checkDisplayConditionsAndParameters(
387:         String parameterPath, String workflowNodeName, Workflow workflow,
388:         WorkflowNodeStructure.OperationType operationType,
389:         Map<String, ?> parameterMap, Map<String, Object> inputMap, Map<String, String> displayConditionMap,
390:         Map<String, ?> dynamicPropertyTypesMap, BaseProperty property, boolean removeParameters) {
391: 
392:         if (property.getDisplayCondition() == null) {
393:             return;
394:         }
395: 
396:         String displayCondition = property.getDisplayCondition();
397: 
398:         if (operationType == WorkflowNodeStructure.OperationType.TASK ||
399:             operationType == WorkflowNodeStructure.OperationType.TASK_DISPATCHER) {
400: 
401:             WorkflowTask workflowTask = workflow.getTask(workflowNodeName);
402: 
403:             Map<String, ?> outputs = workflowNodeOutputFacade.getPreviousWorkflowNodeSampleOutputs(
404:                 workflow.getId(), workflowTask.getName());
405: 
406:             if (displayCondition.contains("[index]")) {
407:                 evaluateArray(
408:                     property.getName(), displayCondition, displayConditionMap, inputMap, (Map<String, Object>) outputs,
409:                     parameterMap);
410:             } else {
411:                 boolean result = evaluateWithOutputs(displayCondition, inputMap, (Map<String, Object>) outputs, parameterMap);
412: 
413:                 if (result) {
414:                     displayConditionMap.put(displayCondition, property.getName());
415:                 }
416:             }
417:         } else {
418:             boolean result = evaluateConditionOnly(displayCondition, MapUtils.concat(inputMap, (Map<String, Object>) parameterMap));
419: 
420:             if (result) {
421:                 displayConditionMap.put(displayCondition, property.getName());
422:             }
423:         }
424: 
425:         if (parameterPath.contains("[")) {
426:             if (removeParameters) {
427:                 List<Integer> parameterPathIndexes = extractIndexes(parameterPath);
428: 
429:                 String indexesString = parameterPathIndexes.stream()
430:                     .map(String::valueOf)
431:                     .collect(Collectors.joining("_"));
432: 
433:                 if (hasExpressionVariable(displayCondition, parameterPath, parameterPathIndexes) &&
434:                     !displayConditionMap.containsValue(String.join("_", indexesString, property.getName()))) {
435: 
436:                     removeParameter(property.getName(), parameterPathIndexes, parameterMap);
437: 
438:                     checkDynamicPropertyType(property.getName(), dynamicPropertyTypesMap);
439:                 }
440:             }
441:         } else {
442:             if (removeParameters && hasExpressionVariable(displayCondition, parameterPath)) {
443:                 removeParameter(property.getName(), null, parameterMap);
444: 
445:                 checkDynamicPropertyType(property.getName(), dynamicPropertyTypesMap);
446:             }
447:         }
448:     }
