578:     @SuppressWarnings("unchecked")
579:     private Map<String, Object> getMetadataMap(String workflowNodeName, Map<String, ?> definitionMap) {
580:         Map<String, Object> metadataMap;
581: 
582:         Map<String, ?> triggerMap = getTrigger(
583:             workflowNodeName, (List<Map<String, ?>>) definitionMap.get(WorkflowExtConstants.TRIGGERS));
584: 
585:         if (triggerMap == null) {
586:             Map<String, ?> taskMap = getTask(
587:                 workflowNodeName, (List<Map<String, ?>>) definitionMap.get(WorkflowConstants.TASKS));
588: 
589:             if (taskMap == null) {
590:                 throw new ConfigurationException(
591:                     "Workflow node with name: %s does not exist".formatted(workflowNodeName),
592:                     WorkflowErrorType.WORKFLOW_NODE_NOT_FOUND);
593:             }
594: 
595:             metadataMap = (Map<String, Object>) taskMap.get(METADATA);
596: 
597:             if (metadataMap == null) {
598:                 metadataMap = new HashMap<>();
599: 
600:                 ((Map<String, Object>) taskMap).put(METADATA, metadataMap);
601:             }
602:         } else {
603:             metadataMap = (Map<String, Object>) triggerMap.get(METADATA);
604: 
605:             if (metadataMap == null) {
606:                 metadataMap = new HashMap<>();
607: 
608:                 ((Map<String, Object>) triggerMap).put(METADATA, metadataMap);
609:             }
610:         }
611: 
612:         return metadataMap;
613:     }
