615:     @SuppressWarnings("unchecked")
616:     private static Map<String, ?> getTask(String workflowNodeName, List<Map<String, ?>> tasksMaps) {
617:         for (Map<String, ?> taskMap : tasksMaps) {
618:             if (Objects.equals(taskMap.get(WorkflowConstants.NAME), workflowNodeName)) {
619:                 if (!taskMap.containsKey(WorkflowConstants.PARAMETERS)) {
620:                     ((Map<String, Object>) taskMap).put(WorkflowConstants.PARAMETERS, new HashMap<>());
621:                 }
622: 
623:                 return taskMap;
624:             }
625: 
626:             Map<String, ?> parameters = (Map<String, ?>) taskMap.get(WorkflowConstants.PARAMETERS);
627: 
628:             if (parameters == null) {
629:                 continue;
630:             }
631: 
632:             for (Map.Entry<String, ?> entry : parameters.entrySet()) {
633:                 if (entry.getValue() instanceof Map<?, ?> curMap) {
634:                     if (curMap.containsKey(WorkflowConstants.NAME)) {
635:                         Map<String, ?> curTaskMap = getTask(workflowNodeName, List.of((Map<String, ?>) curMap));
636: 
637:                         if (curTaskMap != null) {
638:                             return curTaskMap;
639:                         }
640:                     } else {
641:                         for (Map.Entry<?, ?> curMapEntry : curMap.entrySet()) {
642:                             if (curMapEntry.getValue() instanceof Map<?, ?> curTask) {
643:                                 if (!curTask.containsKey(WorkflowConstants.NAME) &&
644:                                     !curTask.containsKey(WorkflowConstants.PARAMETERS)) {
645: 
646:                                     continue;
647:                                 }
648: 
649:                                 Map<String, ?> curTaskMap = getTask(
650:                                     workflowNodeName, List.of((Map<String, ?>) curTask));
651: 
652:                                 if (curTaskMap != null) {
653:                                     return curTaskMap;
654:                                 }
655:                             }
656:                         }
657:                     }
658:                 } else if (entry.getValue() instanceof List<?> curList && !curList.isEmpty() &&
659:                     curList.getFirst() instanceof Map<?, ?>) {
660: 
661:                     for (Object item : curList) {
662:                         Map<String, ?> curTask = (Map<String, ?>) item;
663: 
664:                         if (curTask == null || !curTask.containsKey(WorkflowConstants.NAME) &&
665:                             !curTask.containsKey(WorkflowConstants.PARAMETERS)) {
666: 
667:                             continue;
668:                         }
669: 
670:                         Map<String, ?> curTaskMap = getTask(workflowNodeName, List.of(curTask));
671: 
672:                         if (curTaskMap != null) {
673:                             return curTaskMap;
674:                         }
675:                     }
676:                 }
677:             }
678:         }
679: 
680:         return null;
681:     }
