706:     @SuppressWarnings("unchecked")
707:     private WorkflowNodeStructure getWorkflowNodeStructure(String workflowNodeName, Map<String, ?> definitionMap) {
708:         Map<String, ?> parameterMap;
709:         List<? extends BaseProperty> properties;
710: 
711:         Map<String, ?> triggerMap = getTrigger(
712:             workflowNodeName, (List<Map<String, ?>>) definitionMap.get(WorkflowExtConstants.TRIGGERS));
