839:     private void setDynamicPropertyTypeItem(String path, String type, Map<String, Object> metadataMap) {
840:         Map<String, Object> dynamicPropertyTypesMap = getDynamicPropertyTypesMap(metadataMap);
841: 
842:         if (type == null) {
843:             dynamicPropertyTypesMap.remove(path);
844: 
845:             if (path.contains("[")) {
846:                 List<Integer> pathIndexes = extractIndexes(path);
847:                 String pathPrefix = path.substring(0, path.lastIndexOf("["));
848: 
849:                 for (String key : new HashSet<>(dynamicPropertyTypesMap.keySet())) {
850:                     List<Integer> keyIndexes = extractIndexes(key);
851: 
852:                     if (key.startsWith(pathPrefix) && pathIndexes.getLast() < keyIndexes.getLast()) {
853:                         dynamicPropertyTypesMap.put(
854:                             pathPrefix + "[" + (keyIndexes.getLast() - 1) +
855:                                 path.substring(path.lastIndexOf("[") + 2, path.lastIndexOf("]") + 1),
856:                             dynamicPropertyTypesMap.remove(key));
857:                     }
858:                 }
859:             }
860:         } else {
