324:     @SuppressWarnings("unchecked")
325:     private void checkDisplayConditionsAndParameters(
326:         String parameterPath, String workflowNodeName, Workflow workflow,
327:         WorkflowNodeStructure.OperationType operationType,
328:         Map<String, ?> parameterMap, Map<String, ?> inputMap, Map<String, String> displayConditionMap,
329:         Map<String, ?> dynamicPropertyTypesMap, List<? extends BaseProperty> properties, boolean removeParameters) {
330: 
331:         for (BaseProperty property : properties) {
332:             switch (property) {
333:                 case ArrayProperty arrayProperty -> {
334:                     checkDisplayConditionsAndParameters(
335:                         parameterPath, workflowNodeName, workflow, operationType, parameterMap,
336:                         (Map<String, Object>) inputMap, displayConditionMap, dynamicPropertyTypesMap, arrayProperty,
337:                         removeParameters);
338: 
339:                     checkDisplayConditionsAndParameters(
340:                         parameterPath, workflowNodeName, workflow, operationType, parameterMap,
341:                         inputMap, displayConditionMap, dynamicPropertyTypesMap, arrayProperty.getItems(),
342:                         removeParameters);
343:                 }
344:                 case com.bytechef.platform.workflow.task.dispatcher.domain.ArrayProperty arrayProperty -> {
345:                     checkDisplayConditionsAndParameters(
346:                         parameterPath, workflowNodeName, workflow, operationType, parameterMap,
347:                         (Map<String, Object>) inputMap, displayConditionMap, dynamicPropertyTypesMap, arrayProperty,
348:                         removeParameters);
349: 
350:                     checkDisplayConditionsAndParameters(
351:                         parameterPath, workflowNodeName, workflow, operationType, parameterMap,
352:                         inputMap, displayConditionMap, dynamicPropertyTypesMap, arrayProperty.getItems(),
353:                         removeParameters);
354:                 }
355:                 case ObjectProperty objectProperty -> {
356:                     checkDisplayConditionsAndParameters(
357:                         parameterPath, workflowNodeName, workflow, operationType, parameterMap,
358:                         (Map<String, Object>) inputMap, displayConditionMap, dynamicPropertyTypesMap, objectProperty,
359:                         removeParameters);
360: 
361:                     checkDisplayConditionsAndParameters(
362:                         parameterPath, workflowNodeName, workflow, operationType, parameterMap,
363:                         inputMap, displayConditionMap, dynamicPropertyTypesMap, objectProperty.getProperties(),
364:                         removeParameters);
365:                 }
366:                 case com.bytechef.platform.workflow.task.dispatcher.domain.ObjectProperty objectProperty -> {
367:                     checkDisplayConditionsAndParameters(
368:                         parameterPath, workflowNodeName, workflow, operationType, parameterMap,
369:                         (Map<String, Object>) inputMap, displayConditionMap, dynamicPropertyTypesMap, objectProperty,
370:                         removeParameters);
371: 
372:                     checkDisplayConditionsAndParameters(
373:                         parameterPath, workflowNodeName, workflow, operationType, parameterMap,
374:                         inputMap, displayConditionMap, dynamicPropertyTypesMap, objectProperty.getProperties(),
375:                         removeParameters);
376:                 }
377:                 default -> checkDisplayConditionsAndParameters(
378:                     parameterPath, workflowNodeName, workflow, operationType, parameterMap,
379:                     (Map<String, Object>) inputMap, displayConditionMap, dynamicPropertyTypesMap, property,
380:                     removeParameters);
381:             }
382:         }
383:     }
