498:     private boolean evaluateConditionOnly(String displayCondition, Map<String, ?> inputParameters) {
499:         Map<String, Object> result = evaluator.evaluate(
500:             Map.of("displayCondition", "=" + displayCondition), inputParameters);
501: 
502:         Object displayConditionResult = result.get("displayCondition");
503: 
504:         return !(displayConditionResult instanceof String) && (boolean) displayConditionResult;
505:     }
