507:     private static List<Integer> extractIndexes(String expression) {
508:         List<Integer> indexes = new ArrayList<>();
509: 
510:         Matcher matcher = ARRAY_INDEX_VALUE_PATTERN.matcher(expression);
511: 
512:         while (matcher.find()) {
513:             indexes.add(Integer.parseInt(matcher.group(1)));
514:         }
515: 
516:         return indexes;
517:     }
