769:     private void checkRequiredProperties(
770:         List<?> properties, Map<?, ?> parameterMap, String prefix, List<String> missingRequiredProperties) {
771: 
772:         for (Object prop : properties) {
773:             if (!(prop instanceof BaseProperty property)) {
774:                 continue;
775:             }
776: 
777:             String propertyName = property.getName();
778: 
779:             String propertyPath = prefix.isEmpty() ? propertyName : prefix + "." + propertyName;
780: 
781:             if (property.getRequired() && !parameterMap.containsKey(propertyName)) {
782:                 missingRequiredProperties.add(propertyPath);
783:             } else if (parameterMap.containsKey(propertyName)) {
784:                 // Check nested properties
785:                 if (property instanceof ObjectProperty objectProperty) {
786:                     List<?> nestedProperties = objectProperty.getProperties();
787: 
788:                     if (nestedProperties != null && !nestedProperties.isEmpty()) {
789:                         Object value = parameterMap.get(propertyName);
790: 
791:                         if (value instanceof Map) {
792:                             checkRequiredProperties(
793:                                 nestedProperties, (Map<?, ?>) value, propertyPath, missingRequiredProperties);
794:                         }
795:                     }
796:                 } else if (property instanceof ArrayProperty arrayProperty) {
797:                     List<?> items = arrayProperty.getItems();
798:                     if (items != null && !items.isEmpty()) {
799:                         Object value = parameterMap.get(propertyName);
800: 
801:                         if (value instanceof List<?> list) {
802:                             for (int i = 0; i < list.size(); i++) {
803:                                 Object item = list.get(i);
804: 
805:                                 if (item instanceof Map) {
806:                                     checkRequiredProperties(
807:                                         items, (Map<?, ?>) item, propertyPath + "[" + i + "]",
808:                                         missingRequiredProperties);
809:                                 }
810:                             }
811:                         }
812:                     }
813:                 }
814:             }
815:         }
816:     }
