531:     private static void collectAllIndexCombinationsRecursive(
532:         String displayCondition, Object currentParameters, List<Integer> currentIndexes,
533:         List<List<Integer>> allIndexes) {
534: 
535:         Matcher matcher = ARRAY_INDEXES_PATTERN.matcher(displayCondition);
536: 
537:         if (matcher.find()) {
538:             String key = matcher.group(1);
539:             String indexGroup = matcher.group(2);
540:             String remainingExpression = matcher.group(4);
541: 
542:             if (currentParameters instanceof Map<?, ?> currentParameterMap) {
543:                 if (currentParameterMap.containsKey(key)) {
544:                     Object nextParameters = currentParameterMap.get(key);
545: 
546:                     if (indexGroup != null && nextParameters instanceof List<?> nextList) {
547:                         for (int i = 0; i < nextList.size(); i++) {
548:                             currentIndexes.add(i);
549: 
550:                             collectAllIndexCombinationsRecursive(
551:                                 (indexGroup + remainingExpression).replaceFirst("\\[index]", ""), nextList.get(i),
552:                                 currentIndexes, allIndexes);
553: 
554:                             currentIndexes.removeLast();
555:                         }
556:                     } else {
557:                         collectAllIndexCombinationsRecursive(indexGroup + remainingExpression, nextParameters, currentIndexes, allIndexes);
558:                     }
559:                 }
560:             } else if (currentParameters instanceof List<?> currentList) {
561:                 for (int i = 0; i < currentList.size(); i++) {
562:                     currentIndexes.add(i);
563: 
564:                     collectAllIndexCombinationsRecursive(
565:                         (indexGroup + remainingExpression).replaceFirst("\\[index]", ""), currentList.get(i),
566:                         currentIndexes, allIndexes);
567: 
568:                     currentIndexes.removeLast();
569:                 }
570:             }
571:         } else {
572:             if (!currentIndexes.isEmpty()) {
573:                 allIndexes.add(new ArrayList<>(currentIndexes));
574:             }
575:         }
576:     }
