643:                                 if (!curTask.containsKey(WorkflowConstants.NAME) &&
644:                                     !curTask.containsKey(WorkflowConstants.PARAMETERS)) {
645: 
646:                                     continue;
647:                                 }
648: 
649:                                 Map<String, ?> curTaskMap = getTask(
