87:     @Override
88:     public Map<String, ?> executeAcquire(
89:         String componentName, int connectionVersion, String authorizationName,
90:         Map<String, ?> connectionParameters, Context context) {
91: 
92:         Authorization authorization = componentDefinitionRegistry.getAuthorization(
93:             componentName, connectionVersion, authorizationName);
94: 
95:         try {
96:             return OptionalUtils.get(authorization.getAcquire())
97:                 .apply(ParametersFactory.createParameters(connectionParameters), context);
98:         } catch (Exception e) {
99:             throw new ConfigurationException(e, ConnectionDefinitionErrorType.EXECUTE_ACQUIRE);
100:         }
