103:     @Override
104:     public ApplyResponse executeAuthorizationApply(
105:         String componentName, int connectionVersion, String authorizationName,
106:         Map<String, ?> connectionParameters, Context context) {
107: 
108:         Authorization authorization = componentDefinitionRegistry.getAuthorization(
109:             componentName, connectionVersion, authorizationName);
110: 
111:         ApplyFunction applyFunction = OptionalUtils.orElse(
112:             authorization.getApply(), getDefaultApplyFunction(authorization.getType()));
113: 
114:         try {
115:             return applyFunction.apply(ParametersFactory.createParameters(connectionParameters), context);
116:         } catch (Exception e) {
117:             throw new ConfigurationException(e, ConnectionDefinitionErrorType.EXECUTE_AUTHORIZATION_APPLY);
118:         }
