121:     @Override
122:     public AuthorizationCallbackResponse executeAuthorizationCallback(
123:         String componentName, int connectionVersion, String authorizationName,
124:         Map<String, ?> connectionParameters, Context context, String redirectUri) {
125: 
126:         Authorization authorization = componentDefinitionRegistry.getAuthorization(
127:             componentName, connectionVersion, authorizationName);
128:         String verifier = null;
129: 
130:         if (authorization.getType() == AuthorizationType.OAUTH2_AUTHORIZATION_CODE_PKCE) {
131:             PkceFunction pkceFunction = OptionalUtils.orElse(
132:                 authorization.getPkce(), getDefaultPkceFunction());
133: 
134:             // TODO pkce
135:             Authorization.Pkce pkce;
136: 
137:             try {
138:                 pkce = pkceFunction.apply(null, null, "SHA256", context);
139:             } catch (Exception e) {
140:                 throw new ConfigurationException(
141:                     e, ConnectionDefinitionErrorType.EXECUTE_AUTHORIZATION_CALLBACK);
142:             }
143: 
144:             verifier = pkce.verifier();
145:         }
146: 
147:         AuthorizationCallbackFunction authorizationCallbackFunction = OptionalUtils.orElse(
148:             authorization.getAuthorizationCallback(),
149:             getDefaultAuthorizationCallbackFunction(
150:                 OptionalUtils.orElse(
151:                     authorization.getClientId(),
152:                     (curConnectionParameters, context1) -> getDefaultClientId(
153:                         curConnectionParameters)),
154:                 OptionalUtils.orElse(
155:                     authorization.getClientSecret(),
156:                     (connectionParameters1, curContext) -> getDefaultClientSecret(
157:                         connectionParameters1)),
158:                 OptionalUtils.orElse(
159:                     authorization.getTokenUrl(),
160:                     (connectionParameters1, context1) -> getDefaultTokenUrl(
161:                         connectionParameters1))));
162: 
163:         try {
164:             return authorizationCallbackFunction.apply(
165:                 ParametersFactory.createParameters(connectionParameters),
166:                 MapUtils.getString(connectionParameters, CODE), redirectUri, verifier, context);
167:         } catch (Exception e) {
168:             throw new ConfigurationException(
169:                 e, ConnectionDefinitionErrorType.EXECUTE_AUTHORIZATION_CALLBACK);
170:         }
171:     }
