530:     private static String getDefaultRefreshUrl(
531:         Parameters connectionParameters, TokenUrlFunction tokenUrlFunction, Context context) {
532: 
533:         String refreshUrl = MapUtils.getString(connectionParameters, Authorization.REFRESH_URL);
534: 
535:         if (refreshUrl != null) {
536:             return refreshUrl;
537:         }
538: 
539:         try {
540:             return tokenUrlFunction.apply(connectionParameters, context);
541:         } catch (Exception e) {
542:             throw new ConfigurationException(e, ConnectionDefinitionErrorType.GET_DEFAULT_REFRESH_URL);
543:         }
544:     }
545: 
546:     @SuppressWarnings("unchecked")
547:     private static List<String> getDefaultScopes(Parameters connectionParameters) {
548:         Object scopes = MapUtils.get(connectionParameters, Authorization.SCOPES);
549: 
550:         if (scopes == null) {
551:             return Collections.emptyList();
552:         } else if (scopes instanceof List<?>) {
553:             return (List<String>) scopes;
554:         } else {
555:             return Arrays.stream(((String) scopes).split(","))
556:                 .filter(Objects::nonNull)
557:                 .filter(scope -> !scope.isBlank())
558:                 .map(String::trim)
559:                 .toList();
560:         }
561:     }
