52: 
53:         for (DocumentRecord documentRecord : documentRecords) {
54:             Map<String, Object> document = new HashMap<>();
55: 
56:             document.put("documentBase64", encodeFileEntry(documentRecord.documentFile(), context));
57:             document.put("name", documentRecord.name());
58:             document.put("documentId", documentRecord.documentId());
59: 
60:             documentsList.add(document);
